import { route } from '@hozu/core'
import { z } from 'zod'

export const home = route({ path: '/notes', params: null, search: z.object({ q: z.string().default(''), limit: z.number().int().min(1).default(5) }) })
export const login = route({ path: '/login', params: null, search: z.object({ deleted: z.boolean().default(false) }) })
export const archive = route({ path: '/archive', params: null, search: null })
export const admin = route({ path: '/admin', params: null, search: null })
export const accountDelete = route({ path: '/account/delete', params: null, search: null })
import { project, ui } from '@hozu/core'
import { zodAdapter } from '@hozu/schema-zod'
import { accountDelete, admin, archive, home, login } from './routes.ts'
import { AdminBoard, AdminLink } from './features/admin/views.ts'
import { listUsers } from './features/admin/model.ts'
import { adminFeature } from './features/admin/feature.ts'
import { ArchiveBoard, NotesBoard, notesText } from './features/notes/views.ts'
import { notes } from './features/notes/feature.ts'
import { me, Session } from './features/account/model.ts'
import { AccountBar, accountText, DeleteAccountPage, Login } from './features/account/views.ts'
import { account } from './features/account/feature.ts'

export default project({
  schema: zodAdapter,
  session: Session,
  styles: new URL('./app.css', import.meta.url),
  app: new URL('./app.ts', import.meta.url),
  env: { files: ['.env', '.env.local'] },
  site: { url: 'http://localhost:3000', name: 'app', lang: 'en', locales: ['en', 'de'] },
  routes: { home, login, archive, admin, accountDelete },
  pages: [
    ui.page(login, { views: [Login], head: { render: () => ({ title: accountText.signIn }) } }),
    ui.page(home, {
      views: [AccountBar, AdminLink, NotesBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: notesText.notes, noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(archive, {
      views: [AccountBar, ArchiveBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Archive', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(accountDelete, {
      views: [DeleteAccountPage],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Delete account', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(admin, {
      views: [AccountBar, AdminBoard],
      head: {
        query: listUsers,
        input: () => ({}),
        render: () => ({ title: 'Admin', noindex: true }),
        failed: { Unauthorized: login, NotAdmin: 403 },
      },
    })],
  features: [account, notes, adminFeature],
})
import { endpoint, event, fn, invoke, machine, mutation, on, query, tag } from '@hozu/core'
import { z } from 'zod'

export const Note = z.object({
  id: z.string(),
  number: z.number(),
  title: z.string(),
  pinned: z.boolean(),
  createdAt: z.string(),
  sharedWith: z.array(z.string()),
})
// A note another user shared with the signed-in user: only what the recipient may see.
export const SharedNote = z.object({ id: z.string(), title: z.string(), owner: z.string() })
export const ShareName = z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters')
export const NoteKey = z.object({ id: z.string() })
export const NewNote = z.object({
  title: z.string().trim().min(1, 'Write a note').max(60, 'Use at most 60 characters'),
})

export const Draft = event({ payload: z.object({ title: z.string() }) })
export const Add = event({ payload: z.object({ title: z.string() }) })
export const Remove = event({ payload: NoteKey })
export const Pin = event({ payload: NoteKey })
export const Search = event({ payload: z.object({ q: z.string() }) })
export const Edit = event({ payload: NoteKey })
export const CancelEdit = event({ payload: z.object({}) })
export const Save = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const Archive = event({ payload: NoteKey })
export const Restore = event({ payload: NoteKey })
export const Undo = event({ payload: NoteKey })
export const Select = event({ payload: z.object({ id: z.string(), checked: z.boolean() }) })
export const Share = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const Unshare = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const BulkAction = z.enum(['delete', 'archive'])
export const Bulk = event({ payload: z.object({ ids: z.array(z.string()), action: BulkAction }) })

export const notesTag = tag({ param: null })

// The signed-in user's own notes (archived ones included, shared-with-me ones not), in the list page's order.
export const ExportedNote = z.object({
  title: z.string(),
  pinned: z.boolean(),
  archived: z.boolean(),
  createdAt: z.string(),
})
export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({}),
  output: z.object({ user: z.string(), notes: z.array(ExportedNote) }),
  errors: { Unauthorized: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401 },
})

export const listNotes = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const listArchived = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const addNote = mutation({
  input: NewNote,
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), TooMany: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const removeNote = mutation({
  input: NoteKey,
  output: NoteKey,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const togglePin = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const renameNote = mutation({
  input: z.object({ id: z.string(), title: NewNote.shape.title }),
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const archiveNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const restoreNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// Notes other users shared with the signed-in user (not archived, not deleted).
export const listShared = query({
  input: z.object({}),
  output: z.array(SharedNote),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
import { feature } from '@hozu/core'
import * as model from './model.ts'
import * as views from './views.ts'

export const notes = feature({
  id: 'notes',
  intent: { summary: 'Notes: add one with a title; titles are unique, case-insensitive.' },
  declarations: [model, views],
})

